<script setup lang="ts">
definePageMeta({middleware:['auth','supplier']})
const supabase=useSupabaseClient(); const rows=ref<any[]>([]), loading=ref(true); const q=ref('')
const load=async()=>{loading.value=true; let query=supabase.from('wanted_requests').select('*, companies(name), vehicles(*)').eq('status','open').order('created_at',{ascending:false}); if(q.value.trim()) query=query.ilike('part_name',`%${q.value.trim()}%`); const {data}=await query.limit(100); rows.value=data||[];loading.value=false}
onMounted(load)
</script>
<template><section class="section"><div class="container"><div class="kicker">Supplier portal</div><h1 class="page-title">Wanted Parts</h1><div class="card" style="padding:16px;margin-top:20px;display:flex;gap:10px"><input v-model="q" class="input" placeholder="Search requested part" @keyup.enter="load"><button class="btn btn-primary" @click="load">Search</button></div><div v-if="loading" class="card empty-state">Loading requests…</div><div v-else-if="!rows.length" class="card empty-state">No open wanted requests match.</div><div v-else class="grid" style="gap:14px;margin-top:20px"><NuxtLink v-for="r in rows" :key="r.id" :to="`/supplier/wanted/${r.id}`" class="card" style="padding:20px"><div style="display:flex;justify-content:space-between;gap:12px"><div><h3 style="margin:0">{{r.part_name}}</h3><p class="muted">{{r.preferred_colour||'Any colour'}} · {{r.condition_notes||'Any condition'}}</p></div><div style="text-align:right"><span class="badge">OPEN</span><p class="muted">{{r.delivery_city||''}} {{r.delivery_state_region||''}}</p></div></div></NuxtLink></div></div></section></template>
